const body = $input.first().json.body || $input.first().json || {};
const text = String(body.message?.text || body.text || '').trim();
const chatId = String(body.message?.chat?.id || body.chat_id || '');
const botToken = $env.TELEGRAM_TRADER_BOT_TOKEN || '';
const groqKey = $env.GROQ_API_KEY || '';
const brand = $env.BRAND_NAME || 'Tradesejon';

let reply = `🎯 **${brand} Hyper-Scalping Framework:**\n• WIN BIG, win small, lose small.\n• Strict Stop Loss (1-2% max risk).\n• Live Session: ${$env.LIVE_SESSION_SCHEDULE || 'Mon–Fri 9:30 PM'}`;
if (groqKey && text) {
  const r = await fetch('https://api.groq.com/openai/v1/chat/completions', {
    method: 'POST', headers: { 'Authorization': `Bearer ${groqKey}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      model: 'llama-3.3-70b-versatile',
      messages: [
        { role: 'system', content: `You are ${brand} Trading Mentor Assistant. Guide traders strictly on Hyper-Scalping risk management and supported platforms.` },
        { role: 'user', content: text }
      ]
    })
  }).then(res => res.json()).catch(() => ({}));
  if (r.choices?.[0]?.message?.content) reply = r.choices[0].message.content;
}
if (chatId && botToken) {
  await fetch(`https://api.telegram.org/bot${botToken}/sendMessage`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ chat_id: chatId, text: reply, parse_mode: 'HTML' })
  }).catch(() => null);
}
return [{ json: { ok: true, reply } }];
